const fs=require('node:fs');
const http=require('node:http');
const path=require('node:path');
const {chromium,webkit}=require('playwright');
const ROOT=path.resolve(__dirname,'../..');
const OUT=path.join(ROOT,'_browser_evidence/v368');
const types={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json; charset=utf-8','.webmanifest':'application/manifest+json'};

function server(){return http.createServer((req,res)=>{const pathname=new URL(req.url,'http://127.0.0.1').pathname;const rel=pathname==='/'||pathname==='/index.html'?'app/base-shell-v368.html':decodeURIComponent(pathname).replace(/^\/+/, '');const target=path.resolve(ROOT,rel);if(!target.startsWith(ROOT+path.sep)||!fs.existsSync(target)||!fs.statSync(target).isFile()){res.writeHead(404);res.end('not found');return}const body=fs.readFileSync(target);res.writeHead(200,{'content-type':types[path.extname(target)]||'application/octet-stream','content-length':body.length,'cache-control':'no-store'});res.end(body)})}
async function stable(page){const deadline=Date.now()+45000;for(let i=0;i<8;i++){const remain=Math.max(1000,deadline-Date.now());await page.waitForLoadState('load',{timeout:remain});await page.waitForFunction(()=>window.FEQUEST_APP_BOOT_COMPLETE===true&&window.__FEQ_PAGESHOW_SEEN===true,null,{timeout:remain});await page.waitForFunction(()=>navigator.serviceWorker.controller?.state==='activated',null,{timeout:remain});const origin=await page.evaluate(()=>performance.timeOrigin);await page.waitForTimeout(750);if(await page.evaluate(o=>performance.timeOrigin===o&&window.FEQUEST_APP_BOOT_COMPLETE===true,origin))return;if(Date.now()>=deadline)break}throw new Error('stable boot boundary not reached')}
async function metrics(figure){return figure.evaluate(node=>{const rect=e=>e.getBoundingClientRect();const lineCount=e=>{const range=document.createRange();range.selectNodeContents(e);return [...range.getClientRects()].filter(r=>r.width>0&&r.height>0).length};const panels=[...node.querySelectorAll('.sort-panel-v367')];const heads=panels.map(panel=>panel.querySelector('h4'));const titles=heads.map(head=>head.querySelector('span'));const labels=heads.map(head=>head.querySelector('small'));const firstRows=panels.map(panel=>panel.querySelector('.sort-cells-v367'));const blocks=[node,...node.querySelectorAll('section,div,p,h4,figcaption,code,span')];return{panelWidths:panels.map(e=>rect(e).width),headingHeights:heads.map(e=>rect(e).height),titleLines:titles.map(lineCount),labelLines:labels.map(lineCount),labelWidths:labels.map(e=>rect(e).width),titleAboveLabel:heads.map((head,i)=>rect(titles[i]).bottom<=rect(labels[i]).top+1),arrayWidths:firstRows.map(e=>rect(e).width),overflows:blocks.filter(e=>e.scrollWidth>e.clientWidth+1).map(e=>e.className||e.tagName),documentOverflow:document.documentElement.scrollWidth>innerWidth+1,headingDisplay:heads.map(e=>getComputedStyle(e).display)}})}
async function runCase(type,name,viewport,isMobile=false){const browser=await type.launch();const context=await browser.newContext({viewport,screen:isMobile?viewport:undefined,locale:'ja-JP',isMobile,hasTouch:isMobile,deviceScaleFactor:isMobile?3:1});const page=await context.newPage();await page.addInitScript(()=>{window.__FEQ_PAGESHOW_SEEN=false;addEventListener('pageshow',()=>window.__FEQ_PAGESHOW_SEEN=true,{once:true})});const errors=[],checks=[];let m=null;page.on('pageerror',e=>errors.push(String(e)));const check=(label,value)=>checks.push({label,pass:Boolean(value)});try{const response=await page.goto(globalThis.__BASE__,{waitUntil:'load',timeout:60000});await stable(page);check('HTTP 200 and v368 runtime',response.status()===200&&await page.evaluate(()=>APP_VERSION==='v368'));await page.evaluate(()=>{profile.diagnosticCompleted=true;firstRunGuidedSessionV364=false;document.body.classList.remove('fequest-first-run-v364');document.getElementById('firstRunGuidedV364')?.remove()});const before=await page.evaluate(()=>JSON.stringify({progress:profile.lessonProgress,bProgress:profile.bProgress,xp:profile.xp}));await page.evaluate(()=>startLesson('core_03_03'));const figure=page.locator('.sort-figure-v367');await figure.waitFor({state:'visible'});await figure.evaluate(node=>node.scrollIntoView({block:'start'}));await page.waitForTimeout(150);m=await metrics(figure);check('two equal-width panels',m.panelWidths.length===2&&Math.abs(m.panelWidths[0]-m.panelWidths[1])<=1);check('equal-width array regions',m.arrayWidths.length===2&&Math.abs(m.arrayWidths[0]-m.arrayWidths[1])<=1);if(isMobile){check('mobile headings use the same two-row grid',m.headingDisplay.every(x=>x==='grid')&&m.titleAboveLabel.every(Boolean));check('both titles remain one line',m.titleLines.every(x=>x===1));check('both labels remain one line',m.labelLines.every(x=>x===1));check('mobile heading heights match',Math.abs(m.headingHeights[0]-m.headingHeights[1])<=1);check('mobile label widths match',Math.abs(m.labelWidths[0]-m.labelWidths[1])<=1)}else{check('desktop heading layout is preserved',m.headingDisplay.every(x=>x==='flex'))}check('figure and document do not overflow',m.overflows.length===0&&!m.documentOverflow);check('learning state remains unchanged',await page.evaluate(()=>JSON.stringify({progress:profile.lessonProgress,bProgress:profile.bProgress,xp:profile.xp}))===before);check('no page errors or recovery UI',errors.length===0&&await page.locator('#fequestAssetRecoveryV368').count()===0);fs.mkdirSync(OUT,{recursive:true});await page.screenshot({path:path.join(OUT,`${name}-context.png`)});await figure.screenshot({path:path.join(OUT,`${name}-figure.png`)});return{name,viewport,checks,metrics:m,errors,pass:checks.every(x=>x.pass)}}catch(error){try{fs.mkdirSync(OUT,{recursive:true});await page.screenshot({path:path.join(OUT,`${name}-failure.png`),fullPage:true})}catch{}return{name,viewport,checks,metrics:m,errors,error:error.stack||String(error),pass:false}}finally{await context.close();await browser.close()}}
async function main(){fs.mkdirSync(OUT,{recursive:true});const app=server();await new Promise(resolve=>app.listen(0,'127.0.0.1',resolve));globalThis.__BASE__=`http://127.0.0.1:${app.address().port}/`;let cases;try{cases=[await runCase(chromium,'desktop-chromium-1366',{width:1366,height:900}),await runCase(webkit,'reported-mobile-webkit-402',{width:402,height:874},true),await runCase(webkit,'mobile-webkit-390',{width:390,height:844},true),await runCase(webkit,'narrow-webkit-320',{width:320,height:720},true)]}finally{await new Promise(resolve=>app.close(resolve))}const report={name:'v368-sort-mobile-alignment',cases,result:cases.every(c=>c.pass)?'PASS':'FAIL'};fs.writeFileSync(path.join(OUT,'result.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));if(report.result!=='PASS')process.exitCode=1}
main().catch(error=>{console.error(error);process.exitCode=1});
